def put_away_for_existing_users(apps, schema_editor):
    """Nobody who was already working in Emmaus meets a welcome for the role they already had.

    A person who has signed in at least once (``last_login``) gets every key of the roles they hold today marked as
    put away: their active event memberships, their church role (a church admin is also the administrador of its
    events, a church pastor also its pastor), superusers as administradores, and "sin-rol" for whoever has none of
    them. Roles they receive later show their welcome once, like for anyone new. Reverse: delete these rows.
    """
    User = apps.get_model(settings.AUTH_USER_MODEL)
    OnboardingState = apps.get_model("core", "OnboardingState")
    UserChurchRole = apps.get_model("core", "UserChurchRole")
    EventMembership = apps.get_model("events", "EventMembership")
    now = timezone.now()
    rows = []
    for user in User.objects.filter(last_login__isnull=False).only("id", "is_superuser"):
        keys = {f"rol:{role}" for role in EventMembership.objects.filter(user=user, is_active=True).values_list("role", flat=True)}
        for role in UserChurchRole.objects.filter(user=user).values_list("role", flat=True):
            keys.add(f"iglesia:{role}")
            if role == "church_admin":
                keys.add("rol:administrador")
            elif role == "pastor":
                keys.add("rol:pastor")
        if user.is_superuser:
            keys.add("rol:administrador")
        if not keys:
            keys.add("sin-rol")
        rows.extend(OnboardingState(user=user, key=key, dismissed_at=now) for key in sorted(keys))
    OnboardingState.objects.bulk_create(rows, batch_size=500)


